/* From Uiverse.io by csemszepp - Source: https://codepen.io/GemmaCroad/pen/NWxjrVG - Tags: switch, toggle, toggle switch */
.__UIV_SCOPE__ .switch {
  position: relative;
  display: inline-block;
  width: 60px;
  height: 34px;
}

.__UIV_SCOPE__ .switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.__UIV_SCOPE__ .slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: #6E6E6E;
  transition: .4s;
}

.__UIV_SCOPE__ .slider:before {
  position: absolute;
  content: "";
  height: 26px;
  width: 26px;
  left: 4px;
  bottom: 4px;
  background-color: white;
  transition: .4s;
}

.__UIV_SCOPE__ .input:checked + .slider {
  background-color: #1849AB;
}

.__UIV_SCOPE__ .input:focus + .slider {
  box-shadow: 0 0 0 4px rgba(21, 156, 228, 0.7);
  outline: none;
}

.__UIV_SCOPE__ .input:checked + .slider:before {
  transform: translateX(26px);
}

.__UIV_SCOPE__ .slider.round {
  border-radius: 34px;
}

.__UIV_SCOPE__ .slider.round:before {
  border-radius: 50%;
}
